import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('compiles a static tools schema once across multiple execute calls', async () => {
    // [validated by](src/orchestration/tools/registry.test.ts#L4)
    const registry = new ToolRegistry();
    const schema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    let compileCount = 0;
    const registryAny = registry as {compileSchema: (s: unknown, name: string) => unknown};
    const originalCompile = registryAny.compileSchema.bind(registry);
    registryAny.compileSchema = (s: unknown, name: string) => {
      if (s === schema) compileCount += 1;
      return originalCompile(s, name);
    };

    registry.register(
      {
        name: 'test_tool',
        description: 'Test tool',
        inputSchema: schema,
      },
      async () => 'result'
    );

    for (let i = 0; i < 10; i++) {
      await registry.execute('test_tool', {location: 'test'});
    }

    expect(compileCount).toBe(1);
  });
});

